css:
.loader {
  position: relative;
  width: 56px;
  height: 40px;
  border: 2px solid #c7d2fe;
  border-radius: 4px;
  box-sizing: border-box;
  overflow: hidden;
}
.loader i {
  position: absolute;
  top: 4px;
  left: 4px;
  width: 16px;
  height: 10px;
  border-radius: 3px;
  background: #6366f1;
  animation: bx 1.3s linear infinite alternate, by 1.05s linear infinite alternate;
}
@keyframes bx {
  from { left: 3px; }
  to { left: calc(100% - 19px); }
}
@keyframes by {
  from { top: 3px; }
  to { top: calc(100% - 13px); }
}
